LOCK TABLES `criterion_scales` WRITE;
/*!40000 ALTER TABLE `criterion_scales` DISABLE KEYS */;
INSERT INTO `criterion_scales` VALUES (1,1,1,'Sangat Kurang : Siswa pasif, menunggu instruksi, dan langsung meminta bantuan teacher bahkan sebelum mencoba membaca pesan error.','2026-03-31 19:24:50','2026-03-31 19:24:50'),(2,1,2,'Kurang: Siswa mencoba mengetik sendiri, namun segera menyerah dan memanggil teacher saat menemui kendala kecil atau typo.','2026-03-31 19:24:50','2026-03-31 19:24:50'),(3,1,3,'Cukup: Siswa berani mencoba melakukan perbaikan awal dan bertanya jika logika program masih salah..','2026-03-31 19:24:50','2026-03-31 19:24:50'),(4,1,4,'Baik: Siswa memiliki inisiatif mencari solusi dan hanya bertanya untuk logika yang kompleks.','2026-03-31 19:24:50','2026-03-31 19:24:50'),(5,1,5,'Sangat Baik : Siswa mampu menyelesaikan error dan logika program secara mandiri sepenuhnya, jarang membutuhkan bantuan dari teacher.','2026-03-31 19:24:50','2026-03-31 19:24:50'),(6,2,1,'Sangat Kurang: Siswa sangat lambat, sering tertinggal jauh dari instruksi teacher, perlu waktu yang lebih lama dari teman sebayanya.','2026-03-31 19:25:55','2026-03-31 19:25:55'),(7,2,2,'Kurang: Siswa agak lambat, sering tidak selesai mengerjakan target proyek dalam satu sesi pertemuan.','2026-03-31 19:25:55','2026-03-31 19:25:55'),(8,2,3,'Cukup (Standard): Siswa dapat mengikuti alur kelas dengan baik dan menyelesaikan proyek tepat waktu sesuai durasi bejara di Codero yaiut sealam 1 jam (60 menit).','2026-03-31 19:25:55','2026-03-31 19:25:55'),(9,2,4,'Baik: Siswa cepat memahami konsep, sering selesai lebih awal dari teman sekelasnya.','2026-03-31 19:25:55','2026-03-31 19:25:55'),(10,2,5,'Sangat Baik : Siswa sangat cepat menangkap logika baru, selesai jauh lebih awal, dan biasanya meminta tantangan atau menambah kreasi di proyeknya','2026-03-31 19:25:55','2026-03-31 19:25:55'),(11,3,1,'Sangat Kurang (Fragile): Siswa menunjukkan reaksi negatif yang berlebihan (marah, menangis, membanting mouse, atau tidak mau melanjutkan belajar) saat kodenya gagal.','2026-03-31 19:27:56','2026-03-31 19:27:56'),(12,3,2,'Kurang: Siswa langsung sering mengeluh, menyalahkan komputer atau materi proyek, dan kehilangan motivasi saat bertemu error.','2026-03-31 19:27:57','2026-03-31 19:27:57'),(13,3,3,'Cukup: Siswa bersikap tenang saat error, namun cenderung pasif menunggu teacher datang memperbaiki.','2026-03-31 19:27:57','2026-03-31 19:27:57'),(14,3,4,'Baik: Siswa bersikap tenang, penasaran, dan tekun mencoba mengutak-atik kode untuk memperbaikinya.','2026-03-31 19:27:57','2026-03-31 19:27:57'),(15,3,5,'Sangat Baik (Persistent): Siswa menganggap error sebagai tantangan yang seru, memiliki rasa penasaran tinggi, dan tidak mau dibantu sebelum berhasil menemukan solusinya sendiri.','2026-03-31 19:27:57','2026-03-31 19:27:57'),(16,4,1,'Sangat Kurang: Siswa sangat sering terdistraksi seperti membuka game atau menonton video YouTube dan mengabaikan instruksi teacher.','2026-03-31 19:29:18','2026-03-31 19:29:18'),(17,4,2,'Kurang: Siswa sering melamun, bermain-main benda yang ada di sekitarnya atau mengobrol dengan teman di luar topik pelajaran.','2026-03-31 19:29:18','2026-03-31 19:29:18'),(18,4,3,'Cukup: Siswa fokus mendengarkan, namun sesekali perlu diingatkan atau ditegur teacher untuk kembali fokus belajar.','2026-03-31 19:29:18','2026-03-31 19:29:18'),(19,4,4,'Baik: Siswa fokus mengerjakan proyek, mendengarkan instruksi dengan baik, dan minim distraksi.','2026-03-31 19:29:18','2026-03-31 19:29:18'),(20,4,5,'Sangat Baik : Siswa sangat senang dalam kodingnya, mengabaikan gangguan sekitar, dan perhatian penuh terhadap tugas proyek.','2026-03-31 19:29:18','2026-03-31 19:29:18'),(21,5,1,'Sangat Kurang : Siswa hanya diam , tidak berani bertanya walau bingung, dan menjawab dengan gelengan/anggukan saja saat ditanya.','2026-03-31 19:30:06','2026-03-31 19:30:06'),(22,5,2,'Kurang: Siswa cenderung pasif, hanya berbicara jika ditanya secara langsung oleh teacher.','2026-03-31 19:30:06','2026-03-31 19:30:06'),(23,5,3,'Cukup: Siswa merespon pertanyaan teacher dengan cukup baik dan sesekali bertanya jika ada kendala teknis.','2026-03-31 19:30:06','2026-03-31 19:30:06'),(24,5,4,'Baik: Siswa aktif bertanya mengenai materi dan mampu menjelaskan logika kodenya dengan kalimat yang runut saat diminta presentasi.','2026-03-31 19:30:06','2026-03-31 19:30:06'),(25,5,5,'Sangat Baik : Siswa sangat proaktif, kritis dalam bertanya dan mampu membantu menjelaskan materi kepada dengan baik.','2026-03-31 19:30:06','2026-03-31 19:30:06');
/*!40000 ALTER TABLE `criterion_scales` ENABLE KEYS */;
UNLOCK TABLES;

